pub type Opt = Hit(Int64) | Miss

fn f(p: (Opt, Opt)) -> Int64 {
    return match p {
        (Hit(a), Hit(b)) => a + b
        (Hit(a), Miss) => a
        (Miss, Hit(b)) => b
        (Miss, Miss) => 0
    }
}

